function doseCalc(weight, mgPerKg, times, conc){
  weight=+weight; mgPerKg=+mgPerKg; times=+times; conc=+conc;
  if(!(weight>0)||!(mgPerKg>=0)||!(times>0)) return {error:'体重/剂量/次数须为正'};
  var daily=Math.round(weight*mgPerKg*10)/10;
  var perDose=Math.round(daily/times*10)/10;
  var res={dailyDose:daily, perDose:perDose, times:times};
  if(conc>0) res.volumeMl=Math.round(perDose/conc*10)/10;
  return res;
}
var EXPORTS={doseCalc:doseCalc};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.DrugDoseForgePure = EXPORTS; }
